class CouponScannerPermissionTest {
    @Test
    fun deniedPermissionRequestsInsteadOfOpening() {
        var opened = 0
        var requested = 0
        CouponScanner.scan(hasAccess = false, open = { opened++ }, requestPermission = { requested++ })
        assertEquals(0, opened)
        assertEquals(1, requested)
    }

    @Test
    fun grantedPermissionOpensWithoutRequesting() {
        var opened = 0
        var requested = 0
        CouponScanner.scan(hasAccess = true, open = { opened++ }, requestPermission = { requested++ })
        assertEquals(1, opened)
        assertEquals(0, requested)
    }
}

